// RUN ONCE FOR EACH ITEM — set explicitly, not left on the default.
// A batch approval sends several piece_ids in one POST, so this node must run
// per piece. Leaving it on "run once for all items" would publish only the
// first article and silently drop the rest (July 31 lead-workflow bug).

const cfg = $('Config').first().json;
const p = $json;

const DIR = { es: 'site/blog', en: 'site/en/blog', pt: 'site/pt/blog' };
const URLPATH = { es: '/blog/', en: '/en/blog/', pt: '/pt/blog/' };

// Fail here, not at the API call. An unset githubOwner produces a request to a
// repo that doesn't exist, and GitHub answers 404 — the same code it returns
// for "no permission" and for "file not found". Three very different problems
// wearing one status code sent the first real run chasing token scopes.
for (const k of ['githubOwner', 'githubRepo', 'branch', 'siteBase']) {
  if (!cfg[k] || String(cfg[k]).includes('REPLACE_ME')) {
    throw new Error(`Config node: ${k} is unset (still REPLACE_ME). Fill it in before running.`);
  }
}

if (!DIR[p.language]) {
  throw new Error(`piece ${p.id}: unknown language "${p.language}"`);
}
if (!p.slug || !p.trans_key || !p.body) {
  throw new Error(`piece ${p.id}: missing slug, trans_key or body`);
}

// YAML double-quoted scalar. Same lesson as the writer's JSON body: a colon,
// a quote or a leading dash inside a title breaks the front matter parse and
// takes the whole build down. Quote and escape rather than hope.
const y = (s) =>
  '"' + String(s ?? '').replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';

// `lang` and `layout` are NOT written here — they come from the directory data
// file (site/blog/blog.json etc). Writing them per-file would be a second
// source of truth for something already decided once.
const frontMatter = [
  '---',
  `transKey: ${p.trans_key}`,
  `date: ${p.pub_date}`,
  p.category ? `category: ${y(p.category)}` : null,
  'pageCss: blog.css',
  p.reading_time ? `readingTime: ${p.reading_time}` : null,
  `title: ${y(p.title)}`,
  `headline: ${y(p.headline)}`,
  p.short_title ? `shortTitle: ${y(p.short_title)}` : null,
  p.standfirst ? `standfirst: ${y(p.standfirst)}` : null,
  `description: ${y(p.description)}`,
  '---',
].filter(Boolean).join('\n');

const file = frontMatter + '\n' + String(p.body).trim() + '\n';
const path = `${DIR[p.language]}/${p.slug}.njk`;

return {
  json: {
    piece_id: p.id,
    idea_id: p.idea_id,
    path,
    published_url: `${cfg.siteBase}${URLPATH[p.language]}${p.slug}/`,
    commit_message: `content: publish "${p.headline}" (${p.language})`,
    content_b64: Buffer.from(file, 'utf8').toString('base64'),
    branch: cfg.branch,
    api_url: `https://api.github.com/repos/${cfg.githubOwner}/${cfg.githubRepo}/contents/${path}`,
  },
};

// RUN ONCE FOR EACH ITEM — see the note in "Build .njk file".
// `.item` is the paired-item accessor and only behaves correctly in this mode.

const built = $('Build .njk file').item.json;
const probe = $json;

// 200 = the file is already there and we're replacing it (a re-publish after an
// edit). 404 = new article. Anything else is a real API problem and should not
// be treated as "file is new" — that would blind-overwrite with no sha.
const code = probe.statusCode;
if (code !== 200 && code !== 404) {
  throw new Error(
    `GitHub returned ${code} probing ${built.path}: ` +
    JSON.stringify(probe.body).slice(0, 300)
  );
}

const sha = code === 200 ? probe.body.sha : null;

const commitBody = {
  message: built.commit_message,
  content: built.content_b64,
  branch: built.branch,
};
if (sha) commitBody.sha = sha;

return { json: { ...built, sha, replacing: !!sha, commit_body: commitBody } };

